-- Concept-based drills only (owner, 2026-10-14): never a drill about a person, a book, a bāb, a school's position or
-- where something stands — information gathering. Such kinds are retired here (extra_json.retired); the workers skip them.
UPDATE qr_study_label SET extra_json = json_set(COALESCE(extra_json, '{}'), '$.retired', 1) WHERE scope = 'kind' AND key IN ('adima_heading','adima_note','arc2_disagree','epithet','ex_source','group_of','gt_bab','gt_book','gt_khilaf_basra','gt_khilaf_kufa','gt_khilaf_whose','gt_page','irab_which_book','irab_who_allows','kt_lane','lex_disagree','lex_scholars','lex_which_lexicon','makki_madani','opens_with','shared_opening','surah_intro','tafsir_fiqh','tafsir_school','tafsir_who','tafsir_where','tafsir_xref','tafsir_hadith','translation_who','vocab_books','vocab_who','gs_lesson','gs_bab');
